SELECT organization_id
FROM system_user
WHERE tenant_id = #{tenantId}
  AND id = #{userId}
  AND deleted = 0
LIMIT 1

WITH RECURSIVE organization_tree AS ( SELECT id FROM organization WHERE tenant_id = #{tenantId} AND deleted = 0 AND status = 1 AND id IN
#{rootId}
UNION ALL SELECT child.id FROM organization child JOIN organization_tree parent ON child.parent_id = parent.id WHERE child.tenant_id = #{tenantId} AND child.deleted = 0 AND child.status = 1 ) SELECT DISTINCT id FROM organization_tree
